  if(gameMode==='gameOver'){ resultT-=dt/1000; if(resultT<=0){ gameMode='title'; titleT=0; enemies=[]; playerBullets=[]; enemyBullets=[]; explosions=[]; captureState=null; playerCapturedFreed=false; reserveShown=false; } return; }
  if(gameMode==='play'){ updatePlayer(dt); enterEnemies(dt); updateFormation(dt); tryStartDive(); updateDivers(dt); updateCapture(dt); for(const e of enemies)if(e.captured&&captureState===null){} // safety
    // captured fighter fires when its boss dives
