function updateBullets(dt){ for(const b of playerBullets){ b.x=wrapX(b.x+b.vx*dt/1000); b.y+=b.vy*dt/1000; } playerBullets=playerBullets.filter(b=>b.y>-8); for(const b of enemyBullets){ b.x=wrapX(b.x+b.vx*dt/1000); b.y+=b.vy*dt/1000; } enemyBullets=enemyBullets.filter(b=>b.y<H+8); }

/* ------------------------------ rendering ----------------------------------- */
function render(){ ctx.fillStyle='#000'; ctx.fillRect(0,0,W,H); drawStars(); if(gameMode==='title'){ drawTitle(); return; } drawHUD(); if(gameMode==='stageIntro'){ drawStageIntro(); return; } if(gameMode==='challengeResult'){ drawChallengeResult(); return; } if(gameMode==='gameOver'){ drawGameOver(); return; } drawPlay(); }

function drawStars(){ for(const s of stars){ const tw=0.5+0.5*Math.sin(starTimer*2+s.tw); ctx.globalAlpha=Math.max(0.15,tw); ctx.fillStyle=s.col; ctx.fillRect(s.x,s.y,s.size,s.size);} ctx.globalAlpha=1; }

function drawHUD(){ ctx.textAlign='left'; ctx.font='8px "Courier New",monospace'; ctx.fillStyle=COL.red; ctx.fillText('1UP',4,10); ctx.fillStyle='#fff'; ctx.fillText(String(score).padStart(7,' '),36,10); ctx.textAlign='center'; ctx.fillStyle=COL.red; ctx.fillText('HIGH SCORE',W/2,10); ctx.fillStyle='#fff'; ctx.fillText(String(highScore).padStart(7,' '),W/2,22); drawReserves(); drawFlags(); }
function drawReserves(){ for(let i=0;i<lives-1;i++){ const x=8+i*16; drawSpriteColored(ctx,SPR.fighter,x,H-10,COL.red); } }
function drawFlags(){ let idx=0; for(const f of flags){ if(stage>=f)idx=flags.indexOf(f);} const flagColor=['#ff4b4b','#4b8bff','#ffd23f','#4ad06a','#c07aff','#ff9b2e'][idx]; drawFlag(W-14,H-12,flagColor); }
function drawFlag(x,y,color){ ctx.fillStyle=color; ctx.fillRect(x-5,y-6,10,8); ctx.fillStyle='#fff'; ctx.fillRect(x-4,y-5,7,3); ctx.fillStyle=COL.gray; ctx.fillRect(x+4,y-6,2,12); }

function drawPlay(){ // enemies
  for(const e of enemies){ if(!e.alive)continue; const flap=(Math.floor(starTimer*8)+e.anim)%2; let sprite=e.type==='bee'?SPR.bee:(e.type==='goei'?SPR.goei:SPR.boss); let map=CMAP[e.type]; if(e.type==='boss'&&e.hit)map={1:COL.purple,2:'#fff'}; drawSpriteColored(ctx,sprite,e.x,e.y,map); }
