  ctx.textAlign='center'; ctx.font='9px "Courier New",monospace'; ctx.fillStyle=COL.red; ctx.fillText('HIGH SCORE '+highScore,W/2,H-16); ctx.fillStyle=COL.gray; ctx.fillText('© NAMCO 1981',W/2,H-4);
